import {preferences,keys,write} from './state.mjs';
import {esc,icon} from './ui.mjs';
import {defaults,normalizeSettings} from './settings-model.mjs';
import {validateBackup,planMerge,backupLabels,backupLimit} from './backup-model.mjs';
import {currentBackup,fingerprint,restoreBackup} from './backup-service.mjs';
const $=s=>document.querySelector(s);let session;
export function clearSettingsWork(){session=null;}
export const settingsHasWork=()=>!!(session&&(session.dirty||session.busy));
export function settingsRouteGuard(target){if(!session)return true;const s=session;if(s.busy){s.ctx.notify('正在处理备份，请稍候。');return false;}if(!s.dirty)return true;s.ctx.modal('设置尚未保存','<p class="hub-description">离开前，可以保存这次修改，或放弃修改。</p><div class="settings-actions"><button class="btn secondary" id="settings-stay">继续设置</button><button class="btn secondary" id="settings-discard">放弃修改</button><button class="btn primary" id="settings-save-leave">保存并离开</button></div>');$('#settings-stay').onclick=()=>$('#workspace-dialog').close();$('#settings-discard').onclick=()=>{s.dirty=false;$('#workspace-dialog').close();location.hash=target;};$('#settings-save-leave').onclick=()=>{if(save(s)){ $('#workspace-dialog').close();location.hash=target;}};return false;}
window.addEventListener('beforeunload',e=>{if(settingsHasWork()){e.preventDefault();e.returnValue='';}});
function save(s){try{write(keys.preferences,{...preferences(),...s.values});s.original={...s.values};s.dirty=false;s.ctx.apply();status('设置已保存 · 仅应用于当前浏览器');s.ctx.notify('设置已保存。');return true;}catch{status('保存失败，请检查浏览器存储空间。',true);return false;}}
function status(message,error=false){const el=$('#settings-status');if(el){el.textContent=message;el.classList.toggle('error',error);}}
function preview(s){const box=$('#settings-example');if(box){box.dataset.density=s.values.density;box.dataset.font=s.values.fontSize;box.dataset.theme=s.values.theme;}s.dirty=JSON.stringify(s.values)!==JSON.stringify(s.original);status(s.dirty?'有未保存的修改':'设置已保存于当前浏览器');}
const choice=(name,value,label,description,current)=>`<label class="settings-choice"><input type="radio" name="${name}" value="${value}" ${current===value?'checked':''}><span><b>${label}</b>${description?`<small>${description}</small>`:''}</span></label>`;
export function mountSettings(ctx,section){const tab=section==='privacy'||section==='data'?'data':['writing','shortcuts','notifications'].includes(section)?section:'interface';const values=normalizeSettings(preferences());const s=session={ctx,tab,values,original:{...values},dirty:false,busy:false};$('.dashboard').onclick=null;$('.dashboard').innerHTML=`<div class="hub-heading"><div><h1>设置中心</h1><p>让工作空间更适合你的研究习惯。</p></div><span class="settings-local">${icon('shield',16)} 当前浏览器生效</span></div><div class="settings-layout"><nav class="settings-side-nav" aria-label="设置分类"><div class="settings-nav-header"><b>工作空间设置</b><small>管理你的研究环境</small></div><div class="settings-nav-group"><span class="settings-nav-label">账户</span><a href="#account">${icon('user',18)}<span>账户与安全</span>${icon('arrow',14)}</a><a href="#membership">${icon('diamond',18)}<span>服务与用量</span>${icon('arrow',14)}</a></div><div class="settings-nav-group"><span class="settings-nav-label">工作习惯</span><a href="#settings/writing" ${tab==='writing'?'aria-current="page"':''}>${icon('pen',18)}<span>研究偏好</span>${icon('arrow',14)}</a><a href="#settings" ${tab==='interface'?'aria-current="page"':''}>${icon('grid',18)}<span>界面与体验</span>${icon('arrow',14)}</a><a href="#settings/shortcuts" ${tab==='shortcuts'?'aria-current="page"':''}>${icon('menu',18)}<span>快捷键</span>${icon('arrow',14)}</a></div><div class="settings-nav-group"><span class="settings-nav-label">数据与通知</span><a href="#settings/notifications" ${tab==='notifications'?'aria-current="page"':''}>${icon('bell',18)}<span>通知设置</span>${icon('arrow',14)}</a><a href="#settings/data" ${tab==='data'?'aria-current="page"':''}>${icon('shield',18)}<span>数据与隐私</span>${icon('arrow',14)}</a></div></nav><section class="card settings-main">${tab==='data'?dataPanel():tab==='shortcuts'?shortcutsPanel():tab==='notifications'?notificationPanel(s):preferencePanel(s)}</section><aside class="settings-aside"><section class="card settings-info-card"><span class="more-icon blue">${icon('settings',24)}</span><h3>设置的生效范围</h3><p>写作默认值用于新建项目与任务。界面偏好在保存后生效，已有内容不会被改写。</p></section><section class="card settings-info-card"><span class="more-icon mint">${icon('shield',24)}</span><h3>数据与隐私</h3><p>本地体验资料保存在此浏览器；账户项目分别保存在服务端。更换设备前请备份本地内容。</p><a href="#settings/data">管理数据与备份 ${icon('arrow',13)}</a></section><section class="card settings-info-card settings-billing-card"><span class="more-icon amber">${icon('diamond',24)}</span><h3>服务与用量</h3><p>查看真实保存记录与账户用量。当前不在此处办理购买，在线 AI 以服务配置状态为准。</p><a href="#membership">查看服务与用量 ${icon('arrow',13)}</a></section><section class="card settings-info-card"><span class="more-icon violet">${icon('clock',24)}</span><h3>最近活动</h3><p>请以实际下载的备份文件记录为准。</p><a href="#settings/data">立即备份 ${icon('arrow',13)}</a></section></aside></div><div id="settings-status" class="settings-status" role="status" aria-live="polite">设置已保存于当前浏览器</div>`;
if(tab==='data'){bindData(s);status('导出备份，或选择备份文件进行校验。');return;}if(tab==='shortcuts'){status('说明仅包含当前支持的键盘操作。');return;}$('#settings-form').oninput=()=>{s.values=normalizeSettings({...s.values,...Object.fromEntries(new FormData($('#settings-form'))),...(tab==='notifications'?{localActivityEnabled:$('#setting-local-activity').checked}:{})});preview(s);};$('#settings-form').onsubmit=e=>{e.preventDefault();save(s);};$('#settings-reset').onclick=()=>{ctx.modal('恢复当前分类的默认设置','<p class="hub-description">只重置当前分类的偏好，不删除项目或成果。重置后需要点击保存。</p><button class="btn primary" id="confirm-settings-reset">恢复默认</button>');$('#confirm-settings-reset').onclick=()=>{for(const key of tab==='writing'?['degree','major']:tab==='notifications'?['localActivityEnabled']:['density','fontSize','theme'])s.values[key]=defaults[key];const f=$('#settings-form');for(const [key,value]of Object.entries(s.values)){const field=f.elements.namedItem(key);if(field){if(field.type==='checkbox')field.checked=value;else field.value=value;}}preview(s);$('#workspace-dialog').close();};};preview(s);}
function preferencePanel(s){return `<h2>${s.tab==='writing'?'写作偏好':'界面偏好'}</h2><p class="settings-description">${s.tab==='writing'?'设置常用学段与专业，减少重复填写。':'选择适合你的信息密度与阅读字号。'}</p><form id="settings-form" class="hub-form">${s.tab==='writing'?`<label for="setting-degree">默认学段</label><select name="degree" id="setting-degree">${['专科','本科','硕士','博士','科研人员'].map(d=>`<option ${d===s.values.degree?'selected':''}>${d}</option>`).join('')}</select><label for="setting-major">默认学科专业</label><input name="major" id="setting-major" maxlength="100" value="${esc(s.values.major)}" placeholder="例如：教育学"><p class="hub-footnote">只影响新建内容；每次任务仍可单独调整。</p>`:`<fieldset><legend>列表显示密度</legend><div class="settings-choices">${choice('density','comfortable','舒适','留白充足，便于浏览',s.values.density)}${choice('density','compact','紧凑','更集中地查看记录',s.values.density)}</div></fieldset><fieldset><legend>界面字号</legend><div class="settings-choices font-choices">${choice('fontSize','normal','标准','',s.values.fontSize)}${choice('fontSize','large','较大','',s.values.fontSize)}${choice('fontSize','larger','更大','',s.values.fontSize)}</div></fieldset><fieldset><legend>主题模式</legend><div class="settings-choices theme-choices">${choice('theme','light','浅色','清晰明亮的工作空间',s.values.theme)}${choice('theme','dark','深色','降低夜间阅读刺激',s.values.theme)}${choice('theme','system','跟随系统','自动匹配设备设置',s.values.theme)}</div></fieldset><div class="settings-preview-title">效果预览 <small>示例内容，不会保存为项目</small></div><div id="settings-example"><header>最近项目 <span>预览</span></header><div>${icon('folder',24)}<span><b>我的毕业论文研究</b><small>本科 · 教育学 · 最近编辑</small></span><em>进行中</em></div><div>${icon('file',24)}<span><b>文献综述与研究框架</b><small>论文大纲 · 可继续编辑</small></span><em>草稿</em></div></div><p class="hub-footnote">预览仅作用于上方示例，保存后应用到工作空间。</p>`}<footer class="settings-actions"><button type="button" id="settings-reset" class="btn secondary">恢复默认</button><button class="btn primary" type="submit">保存设置</button></footer></form>`;}
function dataPanel(){return `<h2>本地体验数据与备份</h2><p class="settings-description">把研究资料带走，也能从备份中继续。</p><div class="settings-storage"><span>${icon('shield',24)}</span><div><b>本地体验资料保存在当前浏览器</b><p>此处管理本地项目、草稿、文献笔记和报告；本地草稿不会自动迁移到在线账户。主动上传的账户原件与账户项目由服务器分别保存，此处 JSON 备份不覆盖账户内容。</p></div></div><h3>导出工作空间</h3><p class="settings-description">包含项目、成果草稿、文献与笔记、任务、报告正文、查重对照材料、个人资料、偏好与工具收藏。备份可能包含私人研究资料，请妥善保管。</p><button class="btn secondary" id="settings-export">${icon('file',17)} 导出备份</button><hr><h3>从备份恢复</h3><p class="settings-description">上传 PaperKnow 备份 JSON，先预览，再合并新增记录。重复编号保留当前版本，不覆盖已有内容。</p><label class="settings-upload" for="settings-file">${icon('upload',28)}<b>选择备份文件</b><span>JSON · 最大 50 MB · 版本 1</span><input id="settings-file" type="file" accept=".json,application/json"></label><div id="settings-import-preview"></div><p class="hub-footnote">备份仅覆盖已保存的内容，不包含所有上传原件；未保存的编辑内容需要先保存。</p>`;}
function bindData(s){$('#settings-export').onclick=async()=>{if(s.busy)return;s.busy=true;try{await s.ctx.exportBackup();}finally{s.busy=false;}};$('#settings-file').onchange=async e=>{const file=e.target.files[0];if(!file||s.busy)return;s.busy=true;$('#settings-import-preview').innerHTML='';status('正在校验备份…');try{if(file.size>backupLimit)throw Error('备份超过 50 MB，请选择较小的备份。');const incoming=validateBackup(JSON.parse(await file.text()));const current=await currentBackup();if(session!==s)return;const plan=planMerge(current,incoming),expected=fingerprint(current);$('#settings-import-preview').innerHTML=`<div class="settings-import"><h3>备份预览</h3><p>${esc(file.name)} · ${Math.ceil(file.size/1024)} KB</p><table><thead><tr><th>内容</th><th>新增</th><th>重复跳过</th></tr></thead><tbody>${plan.summary.map(r=>`<tr><td>${backupLabels[r.key]}</td><td>${r.added}</td><td>${r.skipped}</td></tr>`).join('')}</tbody></table>${plan.orphaned?`<p class="error">${plan.orphaned} 条记录关联的项目不在备份或当前空间中，关联暂无法显示。</p>`:''}<label><input type="checkbox" id="settings-personal"> 同时恢复个人资料与偏好（将替换对应设置）</label><p class="hub-footnote">工具收藏会合并；已有项目、成果和报告保留当前版本。</p><button class="btn primary" id="settings-import">确认合并恢复</button><button class="btn secondary" id="settings-import-cancel">取消</button></div>`;$('#settings-import-cancel').onclick=()=>{$('#settings-import-preview').innerHTML='';e.target.value='';status('已取消，当前数据未改变。');};$('#settings-import').onclick=async()=>{if(s.busy)return;s.busy=true;$('#settings-import').disabled=true;status('正在恢复，请勿关闭页面…');try{const summary=await restoreBackup(incoming,expected,{restorePersonal:$('#settings-personal').checked});$('#settings-import-preview').innerHTML='';e.target.value='';status(`恢复完成：新增 ${summary.reduce((n,r)=>n+r.added,0)} 条记录，重复记录已跳过。`);try{await s.ctx.restored();}catch{s.ctx.notify('记录已恢复，但刷新报告列表失败，请重新打开工作台。');}}catch(error){status(error.message||'恢复失败。',true);}finally{s.busy=false;if($('#settings-import'))$('#settings-import').disabled=false;}};status('校验通过，请核对预览后确认恢复。');}catch(error){status(error instanceof SyntaxError?'文件不是有效的 JSON 备份。':error.message,true);e.target.value='';}finally{s.busy=false;}};}

function shortcutsPanel(){return `<h2>快捷键与键盘操作</h2><p class="settings-description">通过键盘完成浏览和常见操作。编辑器内的撤销、复制、粘贴遵循浏览器和系统行为。</p><table class="settings-shortcuts-table"><thead><tr><th>按键</th><th>作用</th></tr></thead><tbody><tr><td><kbd>Esc</kbd></td><td>关闭账户菜单、移动端导航或当前可关闭的对话框</td></tr><tr><td><kbd>Tab</kbd> / <kbd>Shift</kbd> + <kbd>Tab</kbd></td><td>在链接、按钮和表单输入框之间移动焦点</td></tr><tr><td><kbd>Enter</kbd></td><td>打开已聚焦的链接，或提交当前表单</td></tr><tr><td><kbd>Space</kbd></td><td>操作已聚焦的按钮或复选框</td></tr></tbody></table><p class="hub-footnote">暂未提供全局快速新建或自定义快捷键。离开有未保存内容的页面时，仍会提示你先确认。</p>`;}
function notificationPanel(s){return `<h2>通知与动态</h2><p class="settings-description">设置当前浏览器顶部“成果动态”的展示方式。</p><form id="settings-form" class="hub-form"><label class="settings-notification-option"><input type="checkbox" name="localActivityEnabled" id="setting-local-activity" ${s.values.localActivityEnabled?'checked':''}><span><b>显示本地成果动态</b><small>开启后，点击顶部通知图标可查看最近保存的本地成果。关闭后隐藏这些动态；不会删除任何成果。</small></span></label><p class="hub-footnote">此设置仅影响当前浏览器的本地成果动态。账户反馈处理状态在“帮助与反馈”的账户内容中查看；不发送邮件、短信或浏览器推送。</p><footer class="settings-actions"><button type="button" id="settings-reset" class="btn secondary">恢复默认</button><button class="btn primary" type="submit">保存设置</button></footer></form>`;}
